-- Add missing global copy without overwriting tenant or platform edits.
INSERT INTO message_templates (id, "organizationId", key, channel, subject, body, "updatedAt")
SELECT 'pilot-ticket-acknowledgement', NULL, 'ticket.acknowledgement', 'EMAIL', '{"en": "Please acknowledge the event rules", "ru": "Пожалуйста, подтвердите ознакомление с правилами мероприятия", "fr": "Veuillez prendre connaissance des règles de l’événement", "hy": "Խնդրում ենք հաստատել միջոցառման կանոններին ծանոթանալը"}'::jsonb, '{"en": "{{guestName}}, your ticket for {{eventTitle}} is ready. Before check-in, please read and acknowledge the required statements through your personal invitation:\n\n{{link}}\n\nKeep this link private.", "ru": "{{guestName}}, ваш билет на {{eventTitle}} готов. До регистрации на входе ознакомьтесь с обязательными условиями и подтвердите согласие в личном приглашении:\n\n{{link}}\n\nНе передавайте эту ссылку другим.", "fr": "{{guestName}}, votre billet pour {{eventTitle}} est prêt. Avant votre admission, veuillez lire et accepter les conditions requises dans votre invitation personnelle :\n\n{{link}}\n\nGardez ce lien confidentiel.", "hy": "{{guestName}}, Ձեր {{eventTitle}} միջոցառման տոմսը պատրաստ է։ Մուտքի գրանցումից առաջ խնդրում ենք կարդալ և հաստատել պարտադիր պայմանները Ձեր անձնական հրավերում՝\n\n{{link}}\n\nԱյս հղումը պահեք գաղտնի։"}'::jsonb, now()
WHERE NOT EXISTS (SELECT 1 FROM message_templates WHERE "organizationId" IS NULL AND key = 'ticket.acknowledgement' AND channel = 'EMAIL');
